import * as path4 from "node:path";
var generatePackageJson = (dir, opts = {}) => {
  const packageJsonPath = path4.join(dir, "package.json");
  const baseName = opts.packageName || path4.basename(dir);
  const name = opts.packageName || (opts.authorName ? `@tsci/${opts.authorName}.${baseName}` : baseName);
  const packageJsonContent = {
    name,
    version: "1.0.0",
    description: "A tscircuit component package",
    main: "index.tsx",
    keywords: ["tscircuit", "circuit", "pcb", "electronics"],
    scripts: {
      dev: "tsci dev",
      build: "tsci build",
      snapshot: "tsci snapshot",
      "snapshot:update": "tsci snapshot --update",
      start: "tsci dev",
      typecheck: "tsc --noEmit"
    },
    devDependencies: {
      tscircuit: "latest",
      typescript: "^5.0.0"
    }
  };
  if (opts.authorName) {
    packageJsonContent.author = opts.authorName;
  }
  writeFileIfNotExists(packageJsonPath, JSON.stringify(packageJsonContent, null, 2));
};

