// lib/shared/setup-tscircuit-skill.ts
var SKILL_REPO_API_URL = "https://api.github.com/repos/tscircuit/skill/contents";
var SKILL_DIR_NAME = ".claude/skills/tscircuit";
async function fetchGitHubContents(apiUrl) {
  const response = await fetch(apiUrl);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${apiUrl}: ${response.statusText}`);
  }
  return response.json();
}
async function fetchFileContent(downloadUrl) {
  const response = await fetch(downloadUrl);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${downloadUrl}: ${response.statusText}`);
  }
  return response.text();
}
async function downloadDirectory(apiUrl, targetDir) {
  const contents = await fetchGitHubContents(apiUrl);
  for (const item of contents) {
    const targetPath = path5.join(targetDir, item.name);
    if (item.type === "dir") {
      fs4.mkdirSync(targetPath, { recursive: true });
      await downloadDirectory(`${apiUrl}/${item.name}`, targetPath);
    } else if (item.type === "file" && item.download_url) {
      const content = await fetchFileContent(item.download_url);
      fs4.writeFileSync(targetPath, content, "utf-8");
    }
  }
}
async function downloadSkillRepo(targetDir) {
  fs4.mkdirSync(targetDir, { recursive: true });
  const rootContents = await fetchGitHubContents(SKILL_REPO_API_URL);
  for (const item of rootContents) {
    if (item.name === ".git" || item.name === ".github") {
      continue;
    }
    const targetPath = path5.join(targetDir, item.name);
    if (item.type === "dir") {
      fs4.mkdirSync(targetPath, { recursive: true });
      await downloadDirectory(`${SKILL_REPO_API_URL}/${item.name}`, targetPath);
    } else if (item.type === "file" && item.download_url) {
      const content = await fetchFileContent(item.download_url);
      fs4.writeFileSync(targetPath, content, "utf-8");
    }
  }
}
async function setupTscircuitSkill(projectDir, skipPrompt = false) {
  const skillDir = path5.join(projectDir, SKILL_DIR_NAME);
  if (fs4.existsSync(path5.join(skillDir, "SKILL.md"))) {
    console.log("Claude skill already exists, skipping...");
    return true;
  }
  if (!skipPrompt) {
    const { setupSkill } = await prompts({
      type: "confirm",
      name: "setupSkill",
      message: "Would you like to set up tscircuit AI skill for enhanced AI assistance?",
      initial: true
    });
    if (!setupSkill) {
      console.log("Skipping tscircuit skill setup.");
      return false;
    }
  }
  console.info("Setting up tscircuit skill...");
  try {
    await downloadSkillRepo(skillDir);
    console.info(`tscircuit skill installed at ${SKILL_DIR_NAME}`);
    return true;
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    console.warn(kleur_default.yellow(`Failed to set up tscircuit skill: ${errorMessage}`));
    console.warn("Continuing with initialization...");
    return false;
  }
}

