// lib/shared/add-package.ts
function normalizeTscircuitPackageName(packageSpec) {
  if (packageSpec.startsWith("@tscircuit/") || packageSpec.startsWith("@tsci/")) {
    return packageSpec;
  }
  if (packageSpec.startsWith("http://") || packageSpec.startsWith("https://") || packageSpec.startsWith("git+") || packageSpec.startsWith("git://")) {
    return null;
  }
  if (packageSpec.includes("@") && !packageSpec.startsWith("@")) {
    return null;
  }
  if (packageSpec.startsWith("@") && !packageSpec.startsWith("@tsci/") && !packageSpec.startsWith("@tscircuit/")) {
    return null;
  }
  const match = packageSpec.match(/^([^/.@]+)[/.]([^/.@]+)$/);
  if (match) {
    const [, author, componentName] = match;
    return `@tsci/${author}.${componentName}`;
  }
  return null;
}
async function addPackage(packageSpec, projectDir = process.cwd()) {
  const normalizedName = normalizeTscircuitPackageName(packageSpec);
  const displayName = normalizedName || packageSpec;
  let installTarget = normalizedName || packageSpec;
  console.log(kleur_default.cyan(`Adding ${kleur_default.bold(displayName)}...`));
  if (normalizedName?.startsWith("@tsci/")) {
    const npmrcPath = path26.join(projectDir, ".npmrc");
    const npmrcContent = fs24.existsSync(npmrcPath) ? fs24.readFileSync(npmrcPath, "utf-8") : "";
    let hasTsciRegistry = /@tsci[/:]/.test(npmrcContent);
    if (!hasTsciRegistry) {
      const { addRegistry } = await prompts({
        type: "confirm",
        name: "addRegistry",
        message: "No .npmrc entry for @tsci packages was found. Add '@tsci:registry=https://npm.tscircuit.com'?",
        initial: true
      });
      if (addRegistry) {
        const trimmedContent = npmrcContent.trimEnd();
        const newContent = `${trimmedContent.length > 0 ? `${trimmedContent}
` : ""}@tsci:registry=https://npm.tscircuit.com
`;
        fs24.writeFileSync(npmrcPath, newContent);
        console.log(kleur_default.green("✓ Updated .npmrc with tscircuit registry"));
        hasTsciRegistry = true;
      } else {
        console.log("Continuing without updating .npmrc; will fetch package directly from registry tarball.");
      }
    }
    if (!hasTsciRegistry) {
      installTarget = await resolveTarballUrlFromRegistry(normalizedName);
    }
  }
  const packageManager = getPackageManager();
  try {
    packageManager.install({ name: installTarget, cwd: projectDir });
    console.log(kleur_default.green(`✓ Added ${kleur_default.bold(displayName)} successfully`));
    await detectAndSetupKicadLibrary(packageSpec, projectDir);
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    console.error(kleur_default.red(`✗ Failed to add ${displayName}:`), errorMessage);
    handleRegistryAuthError({ error, projectDir });
    throw new Error(`Failed to add ${displayName}: ${errorMessage}`);
  }
}

