// cli/transpile/register.ts
import path57 from "node:path";
var registerTranspile = (program3) => {
  program3.command("transpile").description("Transpile TypeScript/TSX to JavaScript (ESM, CommonJS, and type declarations)").argument("[file]", "Path to the entry file").action(async (file) => {
    try {
      const { projectDir, circuitFiles, mainEntrypoint } = await getBuildEntrypoints({
        fileOrDir: file,
        includeBoardFiles: false
      });
      const distDir = path57.join(projectDir, "dist");
      validateMainInDist(projectDir, distDir);
      console.log("Transpiling entry file...");
      const entryFile = mainEntrypoint || circuitFiles[0];
      if (!entryFile) {
        console.error("No entry file found for transpilation");
        process.exit(1);
      }
      const transpileSuccess = await transpileFile({
        input: entryFile,
        outputDir: distDir,
        projectDir
      });
      if (!transpileSuccess) {
        console.error("Transpilation failed");
        process.exit(1);
      }
      console.log("Transpile complete!");
      process.exit(0);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(message);
      process.exit(1);
    }
  });
};

// lib/shared/register-static-asset-loaders.ts
import fs58 from "node:fs";
import path58 from "node:path";
var TEXT_STATIC_ASSET_EXTENSIONS = [
  ".gltf",
  ".step",
  ".kicad_mod",
  ".kicad_pcb",
  ".kicad_pro",
  ".kicad_sch"
];
var staticAssetFilter = new RegExp(`(${TEXT_STATIC_ASSET_EXTENSIONS.map((ext) => ext.replace(".", "\\.")).join("|")})$`, "i");
var registered = false;
var getBaseUrlFromTsConfig = () => {
  const tsconfigPath = path58.join(process.cwd(), "tsconfig.json");
  try {
    if (!fs58.existsSync(tsconfigPath)) {
      return null;
    }
    const tsconfigContent = fs58.readFileSync(tsconfigPath, "utf-8");
    const tsconfig = JSON.parse(tsconfigContent);
    if (tsconfig.compilerOptions?.baseUrl) {
      return tsconfig.compilerOptions.baseUrl;
    }
  } catch {}
  return null;
};
var registerStaticAssetLoaders = () => {
  if (registered)
    return;
  registered = true;
  if (typeof Bun !== "undefined" && typeof Bun.plugin === "function") {
    const baseUrl = getBaseUrlFromTsConfig();
    Bun.plugin({
      name: "tsci-static-assets",
      setup(build) {
        build.onLoad({ filter: staticAssetFilter }, (args) => {
          const baseDir = baseUrl ? path58.resolve(process.cwd(), baseUrl) : process.cwd();
          const relativePath = path58.relative(baseDir, args.path).split(path58.sep).join("/");
          const pathStr = `./${relativePath}`;
          return {
            exports: {
              __esModule: true,
              default: pathStr
            },
            loader: "object"
          };
        });
      }
    });
  }
};

// cli/doctor/checks/check-login.ts
var checkLoggedIn = () => {
  const name = "Is Logged In to tscircuit.com?";
  const token = getSessionToken();
  if (!token) {
    return {
      name,
      success: false,
      details: "No session token found. Run `tsci auth login` to authenticate."
    };
  }
  return { name, success: true };
};

// cli/doctor/checks/check-npmrc-registry.ts
import { spawnSync } from "node:child_process";
import fs59 from "node:fs";
import os9 from "node:os";
import path59 from "node:path";
var hasBunInstalled = () => {
  const result = spawnSync("bun", ["--version"], { stdio: "ignore" });
  return result.status === 0;
};
var createTempProject = (tempDir) => {
  const packageJsonPath = path59.join(tempDir, "package.json");
  const packageJson = {
    name: "tsci-doctor-check",
    version: "0.0.0",
    private: true,
    dependencies: {
      "@tsci/does-not-exist": "0.0.0"
    }
  };
  fs59.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
};
var checkGlobalNpmrcRegistry = async () => {
  const name = "Global .npmrc configured for tscircuit NPM registry?";
  if (!hasBunInstalled()) {
    return {
      name,
      success: false,
      details: "Bun is required to verify registry settings. Install Bun and rerun `tsci doctor`."
    };
  }
  const tempDir = fs59.mkdtempSync(path59.join(os9.tmpdir(), "tsci-doctor-"));
  try {
    createTempProject(tempDir);
    const result = spawnSync("bun", ["install"], {
      cwd: tempDir,
      env: {
        ...process.env,
        BUN_DEBUG: "network"
      },
      encoding: "utf-8"
    });
    const output = `${result.stdout ?? ""}
${result.stderr ?? ""}`;
    const usedRegistry = /npm\.tscircuit\.com/i.test(output);
    const usedAuthToken = /authorization|_authToken|auth token/i.test(output);
    if (!usedRegistry && !usedAuthToken) {
      return {
        name,
        success: false,
        details: "Bun network logs did not show requests to npm.tscircuit.com or an auth token header. Ensure your global ~/.npmrc includes the tscircuit registry and token from `tsci auth setup-npmrc`."
      };
    }
    if (!usedRegistry) {
      return {
        name,
        success: false,
        details: "Bun network logs did not show requests to npm.tscircuit.com. Your global ~/.npmrc may be missing the tscircuit registry configuration."
      };
    }
    if (!usedAuthToken) {
      return {
        name,
        success: false,
        details: "Bun network logs did not show an auth token header for npm.tscircuit.com. Ensure your global ~/.npmrc contains //npm.tscircuit.com/:_authToken=..."
      };
    }
    return { name, success: true };
  } finally {
    fs59.rmSync(tempDir, { recursive: true, force: true });
  }
};

// cli/doctor/run-doctor.ts
var formatResult = (result) => {
  const icon = result.success ? kleur_default.green("☑") : kleur_default.red("✗");
  console.log(`${icon} ${result.name}`);
  if (!result.success && result.details) {
    console.log(kleur_default.red(`  ↳ ${result.details}`));
  }
};
var runDoctor = async () => {
  const results = [];
  results.push(checkLoggedIn());
  results.push(await checkGlobalNpmrcRegistry());
  console.log(kleur_default.bold(`
Doctor checks:`));
  results.forEach(formatResult);
  const failed = results.filter((result) => !result.success);
  if (failed.length > 0) {
    process.exitCode = 1;
  }
};

// cli/doctor/register.ts
var registerDoctor = (program3) => {
  program3.command("doctor").description("Run diagnostic checks for your tscircuit setup").action(async () => {
    await runDoctor();
  });
};

